-- id:       view-escalation-chain
-- title:    Escalation chains (view)
-- concept:  vw_escalation_chain · joins escalation, policy and the user directory
-- rubric:   8 · View
-- purpose:  Every escalation step with who it came from and who it went to. Level 1 goes to the department head, 2 to the ward admin, 3 to the commissioner.
-- GENERATED by web/scripts/export-queries.ts from src/lib/data/mock/lab.ts. Edit there, then run npm run db:queries.

SELECT complaint_id, escalation_level, level_label,
       escalated_from_name, escalated_to_name, escalated_to_role, still_open
FROM vw_escalation_chain
ORDER BY complaint_id DESC, escalation_level
LIMIT 20;
